import os,json,argparse
import numpy as np
a=argparse.ArgumentParser();a.add_argument('cmd');a.add_argument('--inputs');a.add_argument('--out');a.add_argument('--seed',type=int,default=0);g=a.parse_args()
os.makedirs(g.out,exist_ok=True)
r={'files':[]}
for d,_,fs in os.walk(g.inputs):
    for f in fs:
        p=os.path.join(d,f);e={'path':p,'size':os.path.getsize(p)}
        try:
            if f.endswith('.npz'):
                z=np.load(p)
                for k in z.files:
                    e[k]=[list(z[k].shape),str(z[k].dtype)]
                if 'y' in z.files:
                    e['ybincount']=np.bincount(z['y']).tolist()
        except Exception as x:
            e['err']=str(x)
        r['files'].append(e)
json.dump(r,open(os.path.join(g.out,'diag.json'),'w'),indent=1)
print(json.dumps(r))
